#!/usr/bin/env node
"use strict";

// Generated by packaging/sync.py. Downloads the matching GitHub release
// binary and verifies its SHA-256 before installing it.
const fs = require("node:fs");
const path = require("node:path");
const https = require("node:https");
const crypto = require("node:crypto");
const { version } = require("./package.json");

const NAME = "ddc";
const ENV_PREFIX = "DDC";
const ASSETS = {
  "darwin-arm64": {
    url: "https://github.com/ejfkdev/ddc/releases/download/v0.1.35/ddc-v0.1.35-aarch64-apple-darwin",
    sha256: "d9292e2a4eb89248bbdfedce56363a07ec72c7590238c001449f957eb2768e6d",
  },
  "darwin-x64": {
    url: "https://github.com/ejfkdev/ddc/releases/download/v0.1.35/ddc-v0.1.35-x86_64-apple-darwin",
    sha256: "753dd7fec32c7fd2e02133a0d1fbdb4fb971b7855741ee0ff19c37e3adba87bc",
  },
  "linux-arm64": {
    url: "https://github.com/ejfkdev/ddc/releases/download/v0.1.35/ddc-v0.1.35-aarch64-unknown-linux-gnu",
    sha256: "dbb734cf98c4b22ea166a71adc892718dba263628a346718178f483ad5d4f38d",
  },
  "linux-arm64-musl": {
    url: "https://github.com/ejfkdev/ddc/releases/download/v0.1.35/ddc-v0.1.35-aarch64-unknown-linux-musl",
    sha256: "15cea25b77b4aba1ed128db41892e52de4cc7bea310216b6460c77f0aab32904",
  },
  "linux-x64": {
    url: "https://github.com/ejfkdev/ddc/releases/download/v0.1.35/ddc-v0.1.35-x86_64-unknown-linux-gnu",
    sha256: "81b912dcf355b3fb7c44fee8bf0510710a5dc0ce982f7abf28917bdfdf6a0f37",
  },
  "linux-x64-musl": {
    url: "https://github.com/ejfkdev/ddc/releases/download/v0.1.35/ddc-v0.1.35-x86_64-unknown-linux-musl",
    sha256: "ec8f852bace04637def5499040bc7812a7259ba2764b73bd297f65da820ae6ee",
  },
  "win32-arm64": {
    url: "https://github.com/ejfkdev/ddc/releases/download/v0.1.35/ddc-v0.1.35-aarch64-pc-windows-msvc.exe",
    sha256: "efd2ecab26c4accd804e9d4c979f830a5b9396bec60b670263133a9a419cda3c",
  },
  "win32-x64": {
    url: "https://github.com/ejfkdev/ddc/releases/download/v0.1.35/ddc-v0.1.35-x86_64-pc-windows-msvc.exe",
    sha256: "e82152907581158fded6583ed12b47029bf415030fe7b1eb96e687effd3a0e64",
  },
};

function fail(message) {
  console.error(`${NAME}: ${message}`);
  process.exit(1);
}

function isMusl() {
  if (process.platform !== "linux") return false;
  try {
    return !process.report.getReport().header.glibcVersionRuntime;
  } catch (_) {
    return (
      fs.existsSync("/lib/ld-musl-x86_64.so.1") ||
      fs.existsSync("/lib/ld-musl-aarch64.so.1")
    );
  }
}

function download(url, dest, redirects) {
  if (redirects === undefined) redirects = 0;
  return new Promise((resolve, reject) => {
    const request = https.get(
      url,
      {
        headers: { "User-Agent": `${NAME}-npm-installer/${version}` },
        timeout: 120000,
      },
      (response) => {
        const status = response.statusCode || 0;
        if (status >= 300 && status < 400 && response.headers.location) {
          response.resume();
          if (redirects >= 10) {
            reject(new Error(`too many redirects for ${url}`));
            return;
          }
          const next = new URL(response.headers.location, url).toString();
          download(next, dest, redirects + 1).then(resolve, reject);
          return;
        }
        if (status !== 200) {
          response.resume();
          reject(new Error(`HTTP ${status} for ${url}`));
          return;
        }
        const hash = crypto.createHash("sha256");
        const out = fs.createWriteStream(dest, { mode: 0o755 });
        response.on("data", (chunk) => hash.update(chunk));
        response.on("error", reject);
        out.on("error", reject);
        out.on("finish", () => resolve(hash.digest("hex")));
        response.pipe(out);
      }
    );
    request.on("error", reject);
    request.on("timeout", () => {
      request.destroy(new Error(`download timed out for ${url}`));
    });
  });
}

async function downloadWithRetry(url, dest) {
  let last;
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    try {
      return await download(url, dest, 0);
    } catch (error) {
      last = error;
      fs.rmSync(dest, { force: true });
      if (attempt < 3) {
        console.error(
          `${NAME}: download failed (${error.message}); retrying (${attempt}/3)...`
        );
        await new Promise((resolve) => setTimeout(resolve, attempt * 2000));
      }
    }
  }
  throw last;
}

async function main() {
  const platform = process.platform;
  const arch = process.arch;
  const key = isMusl() ? `${platform}-${arch}-musl` : `${platform}-${arch}`;

  const binDir = path.join(__dirname, "bin");
  const fileName = platform === "win32" ? `${NAME}.exe` : NAME;
  const dest = path.join(binDir, fileName);
  const tmp = path.join(binDir, `.${NAME}-download-${process.pid}`);
  fs.mkdirSync(binDir, { recursive: true });

  const local = process.env[`${ENV_PREFIX}_BINARY_PATH`];
  if (local) {
    try {
      fs.copyFileSync(local, dest);
      if (platform !== "win32") fs.chmodSync(dest, 0o755);
      console.log(`${NAME}: installed from ${local}`);
    } catch (error) {
      fail(`cannot copy ${ENV_PREFIX}_BINARY_PATH (${local}): ${error.message}`);
    }
    return;
  }

  const meta = ASSETS[key];
  if (!meta) {
    fail(
      `no prebuilt binary for ${key}; supported: ${Object.keys(ASSETS).join(", ")}. ` +
        `Set ${ENV_PREFIX}_BINARY_PATH to a local ${NAME} binary instead.`
    );
  }

  try {
    const actual = await downloadWithRetry(meta.url, tmp);
    if (actual !== meta.sha256) {
      throw new Error(
        `sha256 mismatch for ${meta.url}: expected ${meta.sha256}, got ${actual}`
      );
    }
    fs.rmSync(dest, { force: true });
    fs.renameSync(tmp, dest);
    if (platform !== "win32") fs.chmodSync(dest, 0o755);
    console.log(`${NAME} ${version} installed (${key})`);
  } catch (error) {
    fs.rmSync(tmp, { force: true });
    fail(
      `${error.message}\n  Download it manually from ${meta.url} and set ` +
        `${ENV_PREFIX}_BINARY_PATH.`
    );
  }
}

main().catch((error) => fail(error && error.stack ? error.stack : String(error)));
